package com.seminarhub.domain.seminar.repository.querydsl;
import static com.seminarhub.domain.seminar.domain.QMemberSeminarPaymentHistory.memberSeminarPaymentHistory;
import com.querydsl.core.BooleanBuilder; import com.querydsl.core.types.dsl.ComparableExpressionBase; import com.querydsl.jpa.impl.JPAQueryFactory;
import com.seminarhub.domain.seminar.domain.MemberSeminarPaymentHistory; import com.seminarhub.domain.seminar.service.MemberSeminarPaymentHistorySearchQuery; import com.seminarhub.global.dto.CursorRequest; import com.seminarhub.global.repository.QuerydslRepositorySupport;
import java.util.List; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Repository;
@Repository public class MemberSeminarPaymentHistoryRepositoryImpl extends QuerydslRepositorySupport<MemberSeminarPaymentHistory> implements MemberSeminarPaymentHistoryRepositoryCustom {
    public MemberSeminarPaymentHistoryRepositoryImpl(JPAQueryFactory f){super(f,memberSeminarPaymentHistory,memberSeminarPaymentHistory.id,memberSeminarPaymentHistory.createdAt,memberSeminarPaymentHistory.updatedAt,memberSeminarPaymentHistory.deletedAt);} public List<MemberSeminarPaymentHistory> search(MemberSeminarPaymentHistorySearchQuery q){return findAll(condition(q));} public Page<MemberSeminarPaymentHistory> search(MemberSeminarPaymentHistorySearchQuery q,Pageable p){return findAll(condition(q),p,this::sort);} public List<MemberSeminarPaymentHistory> search(MemberSeminarPaymentHistorySearchQuery q,CursorRequest c){return findByCursor(condition(q),c);}
    private BooleanBuilder condition(MemberSeminarPaymentHistorySearchQuery q){BooleanBuilder b=auditCondition(q);if(q.amount()!=null)b.and(memberSeminarPaymentHistory.amount.eq(q.amount()));if(q.amountMin()!=null)b.and(memberSeminarPaymentHistory.amount.goe(q.amountMin()));if(q.amountMax()!=null)b.and(memberSeminarPaymentHistory.amount.loe(q.amountMax()));return b;} private ComparableExpressionBase<?> sort(String n){return switch(n){case"id"->memberSeminarPaymentHistory.id;case"amount"->memberSeminarPaymentHistory.amount;case"createdAt"->memberSeminarPaymentHistory.createdAt;case"updatedAt"->memberSeminarPaymentHistory.updatedAt;case"deletedAt"->memberSeminarPaymentHistory.deletedAt;default->null;};}
}
